/* root node for the linked list of users */
struct user* root = NULL;

/* check whether the entered user already exist or not */
uint8_t check_exist ( char *new_user ) {

    struct user *temp = root;
    
    /* check for root node null error */
    if ( root == NULL ) {
        return -1;
    }

    while ( 1 ) {
        if ( !(strcmp(temp->name,new_user)) ) {
            return 1;
        }
        if ( temp->next != NULL ) {
            temp = temp->next;
        }
        else {
            return 0;
        }
    }
}

/* function to add node in user data linked list ( new node is being added at the end ) */
struct user* add_user ( struct user *head, char *ta_usr_value, char *ta_pswd_value) {

    struct user* temp = head;
    char * node_usr_value = NULL;           /* pointer to memory storing username */
    char * node_pswd_value = NULL;          /* pointer to memory storing password */

    /* if the node is root node */
    if ( head == NULL ) {
        if ( (head = (struct user *)malloc(sizeof(struct user))) == NULL ) {    /* assigning memory to a node of linked list */
            ESP_LOGD(TAG,"couldn't allocate dynamic memory");
            return head;
        }
        if ( (node_usr_value = (char *)malloc( sizeof(char) * strlen(ta_usr_value) )) == NULL ) {
            ESP_LOGD(TAG,"couldn't allocate dynamic memory");
            free(head);
            return NULL;
        }
        if ( (node_pswd_value = (char *)malloc( sizeof(char) * strlen(ta_pswd_value) )) == NULL ) {
            ESP_LOGD(TAG,"couldn't allocate dynamic memory");
            free(head);
            return NULL;
        }

        strcpy( node_usr_value, ta_usr_value );
        strcpy( node_pswd_value, ta_pswd_value );
        
        head->name = node_usr_value;
        head->pswd = node_pswd_value;
        head->next = NULL;
        return head;
    }

    /* finding for the last node of linked list */
    while ( temp->next != NULL ) {
        temp = temp->next;
    }
    /* creating new node in the end and storing username and password there */
    if ( (temp->next = (struct user *)malloc(sizeof(struct user))) == NULL ) {      /* assigning memory to new node of linked list */
        ESP_LOGD(TAG,"couldn't allocate dynamic memory");
        return head;
    }   
    temp = temp->next;
    if ( (node_usr_value = (char *)malloc( sizeof(char) * strlen(ta_usr_value) ))  == NULL) {       /* allocating memory to username string */
        ESP_LOGD(TAG,"couldn't allocate dynamic memory");
        free(temp->next);
        return head;
    }

    if ( (node_pswd_value = (char *)malloc( sizeof(char) * strlen(ta_pswd_value) ))  == NULL) {       /* allocating memory to password string */
        ESP_LOGD(TAG,"couldn't allocate dynamic memory");
        free(node_usr_value);
        free(temp->next);
        return head;
    }

    strcpy( node_usr_value, ta_usr_value );                             /* copying text area's input to allocated memory*/
    strcpy( node_pswd_value, ta_pswd_value );                           /* copying text area's input to allocated memory*/

    /* giving pointers to node */
    temp->name = node_usr_value; 
    temp->pswd = node_pswd_value;
    temp->next = NULL;

    return head;
}

