/* callback function for submit button of add user panel */
void usr_config(lv_event_t * e)
{
    uint8_t i = 0;                                                                      /* variable for iterating through both inputs */
    char *usrnm = (char *)lv_textarea_get_text(ui_usrNmBx);
    char *pswd =  (char *)lv_textarea_get_text(ui_pswdBx);

    /* handle empty input case */
    if ( *usrnm == '\0' || *pswd == '\0' ) {
        _ui_flag_modify(ui_BxEmptyMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);       /* shows empty input error message on screen */
        _ui_flag_modify(ui_lengthMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides input length error message on screen */
        _ui_flag_modify(ui_invldIpMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides invalid input error message on screen */
        _ui_flag_modify(ui_usrExstMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides user exists error message on screen */
        /* empty text area for username and password */
        lv_textarea_set_text(ui_usrNmBx, "");
        lv_textarea_set_text(ui_pswdBx, "");
        return;
    }

    /* handle input length error */
    if ( strlen(usrnm) < 4 || strlen(pswd) < 4 ) {
        _ui_flag_modify(ui_lengthMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);       /* shows input length error message on screen */
        _ui_flag_modify(ui_BxEmptyMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides empty input error message on screen */
        _ui_flag_modify(ui_invldIpMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides invalid input error message on screen */
        _ui_flag_modify(ui_usrExstMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides user exists error message on screen */
        /* empty text area for username and password */
        lv_textarea_set_text(ui_usrNmBx, "");
        lv_textarea_set_text(ui_pswdBx, "");
        return;
    }

    /* check for invalid input ( only numbers are alowd */
    while ( pswd[i] != '\0' ) {
        if ( !(isdigit((uint8_t)pswd[i++])) ) {
            _ui_flag_modify(ui_invldIpMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);       /* shows invalid input error message on screen */
            _ui_flag_modify(ui_lengthMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides input length error message on screen */
            _ui_flag_modify(ui_usrExstMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides user exists error message on screen */
            _ui_flag_modify(ui_BxEmptyMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides empty input error message on screen */
            /* empty text area for username and password */
            lv_textarea_set_text(ui_usrNmBx, "");
            lv_textarea_set_text(ui_pswdBx, "");
            return;
        }
    }
    i = 0;
    while ( usrnm[i] != '\0' ) {
        if ( !(isdigit((uint8_t)usrnm[i++])) ) {
            _ui_flag_modify(ui_invldIpMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);       /* shows invalid input error message on screen */
            _ui_flag_modify(ui_lengthMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides input length error message on screen */
            _ui_flag_modify(ui_usrExstMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides user exists error message on screen */
            _ui_flag_modify(ui_BxEmptyMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);       /* hides empty input error message on screen */
            /* empty text area for username and password */
            lv_textarea_set_text(ui_usrNmBx, "");
            lv_textarea_set_text(ui_pswdBx, "");
            return;
        }
    }

    /* check whether user already exist or not */
    if (root != NULL && check_exist(usrnm) ) {
        _ui_flag_modify(ui_usrExstMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);       /* shows user exists error message on screen */
        _ui_flag_modify(ui_lengthMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);           /* hides input length error message on screen */
        _ui_flag_modify(ui_BxEmptyMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);          /* hides empty input error message on screen */
        _ui_flag_modify(ui_invldIpMsg, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);          /* hides invalid input error message on screen */
        /* empty text area for username and password */
        lv_textarea_set_text(ui_usrNmBx, "");
        lv_textarea_set_text(ui_pswdBx, "");
        return;
    }

    /* add user */
    root = add_user (root, usrnm, pswd);
    /* empty text area for username and password */
    lv_textarea_set_text(ui_usrNmBx, "");
    lv_textarea_set_text(ui_pswdBx, "");
    if ( root != NULL ) {
        update_table();
    }
    _ui_screen_change(&ui_Screen6, LV_SCR_LOAD_ANIM_FADE_OUT, 500, 0, &ui_Screen6_screen_init);


}

