/* callback function for clear user list button on operator list panel */
void clr_usr_list(lv_event_t * e)
{
    /* return from function if linked list is already empty */
    if ( root == NULL ) {
        return;
    }
    delete_users(root);

    /* a temporary variable for traveling between nodes */
    struct user* temp = root;
    
    /* iteratively free last node inside list */
    while ( root->next != NULL ) {
        temp = root;
        while ( temp->next->next != NULL ) {
            temp = temp->next;
        }
        free(temp->next);
        temp->next = NULL;
    }
    free(root);
    root = NULL;

    /* function that clears all data inside table of operator list table */
    clr_table(ui_table);
}

void wifi_cnfg(lv_event_t * e)
{
    const char* ssid = lv_textarea_get_text(ui_wifiSSIDBx);
    const char* pass = lv_textarea_get_text(ui_wifiPswdBx);

    memcpy(gWifi_ssid, ssid,strlen(ssid) + 1);
    memcpy(gWifi_pass, pass,strlen(pass) + 1);

    wifi_config_t wifi_data = {0};

    memcpy(wifi_data.sta.ssid, gWifi_ssid,strlen((char*)gWifi_ssid)+1);
    memcpy(wifi_data.sta.password, gWifi_pass,strlen((char*)gWifi_pass)+1);

    printf("new_ssid=%s\n",wifi_data.sta.ssid);
    printf("new_pswd=%s\n",wifi_data.sta.password);

    if(mqtt_client!=NULL){
        esp_mqtt_client_stop(mqtt_client);
    }

    esp_wifi_disconnect();
    vTaskDelay(1000/portTICK_PERIOD_MS);
    esp_wifi_stop();
    vTaskDelay(1000/portTICK_PERIOD_MS);
    
    esp_wifi_set_mode(WIFI_MODE_STA);
    esp_wifi_set_config(WIFI_IF_STA, &wifi_data);//sets the wifi data configuration
    esp_wifi_start();
    vTaskDelay(1000/portTICK_PERIOD_MS);
    esp_wifi_connect();//connect wifi station to AP

    lv_textarea_set_text(ui_wifiSSIDBx, "");
    lv_textarea_set_text(ui_wifiPswdBx, "");

    //wifi_init();
    //vTaskDelay(1000);
    //vTaskResume(gWifi_handle);
}
